import sarf_gen as g
from sarf_gen import (derived, derived_naqis, derived_hollow, sound1, naqis1, hollow1, entry, mazi14, mudari14, idgham,
                      mazi_naqis_kasra, mudari_naqis, amr_naqis, B2, B3, B4, B5, B6, B7, B8, B10, W2, W3, W4, W5, W6, W7, W8, W10)
