def IV(f, a, l, note=None):
    return derived(B4, W4, "ُ", f"أَ{f}ْ{a}َ{l}", f"{f}ْ{a}ِ{l}", f"أَ{f}ْ{a}ِ{l}", f"إِ{f}ْ{a}َا{l}", f"مُ{f}ْ{a}ِ{l}", f"مُ{f}ْ{a}َ{l}", f"أُ{f}ْ{a}ِ{l}َ", f"يُ{f}ْ{a}َ{l}ُ", note=note)
def Vf(f, a, l, passive=False, note=None):
    st = f"تَ{f}َ{a}َّ{l}"
    return derived(B5, W5, "َ", st, st, st, f"تَ{f}َ{a}ُّ{l}", f"مُتَ{f}َ{a}ِّ{l}", *( (f"مُتَ{f}َ{a}َّ{l}", f"تُ{f}ُ{a}ِّ{l}َ", f"يُتَ{f}َ{a}َّ{l}ُ") if passive else () ), note=note)
def VI(f, a, l, note=None):
    st = f"تَ{f}َا{a}َ{l}"
    return derived(B6, W6, "َ", st, st, st, f"تَ{f}َا{a}ُ{l}", f"مُتَ{f}َا{a}ِ{l}", note=note)
def V_naqis(f, a, note=None):
    b = f"تَ{f}َ{a}َّ"; bb = f"تَ{f}َ{a}ّ"
    return derived_naqis(B5 + " — نَاقِصٌ", W5, "َ", b, bb, "a", bb, f"تَ{f}َ{a}ٍّ (التَّ{f}َ{a}ِّي)", f"مُتَ{f}َ{a}ٍّ (الْمُتَ{f}َ{a}ِّي)", note=note)
def VI_naqis(f, a, note=None):
    b = f"تَ{f}َا{a}َ"; bb = f"تَ{f}َا{a}"
    return derived_naqis(B6 + " — نَاقِصٌ", W6, "َ", b, bb, "a", bb, f"تَ{f}َا{a}ٍ (التَّ{f}َا{a}ِي)", f"مُتَ{f}َا{a}ٍ (الْمُتَ{f}َا{a}ِي)", note=note)
def VIII(v, core, amr, masdar, fail, maful=None, pmz=None, pmd=None, bab=B8, wazn=W8, note=None):
    return derived(bab, wazn, "َ", v, core, amr, masdar, fail, maful, pmz, pmd, note=note)
def dbl_if(bab, wazn, pre, f, a, l, masdar, fail, maful=None, pmz=None, pmd=None, note=None):
    """the doubled verb of اِفْتَعَلَ / اِنْفَعَلَ: pre = «اِ» + the bāb's letters before the ʿayn (written with the fāʾ)"""
    c = f"{pre}{a}َ{l}ّ"; full = f"{pre}{a}َ{l}َ{l}"; mc = f"{pre[2:]}{a}َ{l}ّ"; mfull = f"{pre[2:]}{a}َ{l}ِ{l}"
    amr = [c + "َ", c + "َا", c + "ُوا", c + "ِي", c + "َا", f"{pre}{a}َ{l}ِ{l}ْنَ"]
    y = "يَ" + mc
    return doubled(bab, wazn, masdar, fail, c, full, "َ", mc, mfull, amr, y + "َ", y + "َ", "تَ" + mc + "َ", maful, pmz, pmd, note)

