V["istaqsa"]  = derived_naqis(B10 + " — نَاقِصٌ", W10, "َ", "اِسْتَقْصَ", "سْتَقْص", "i", "اِسْتَقْص", "اِسْتِقْصَاء", "مُسْتَقْصٍ (الْمُسْتَقْصِي)", "مُسْتَقْصًى", "اُسْتُقْصِيَ", "يُسْتَقْصَى")
