# ---------------------------------------------------------------- the bābs of colour and the rarer augments
def IX(f, a, l, masdar_note=None):
    c = f"اِ{f}ْ{a}َ{l}ّ"; full = f"اِ{f}ْ{a}َ{l}َ{l}"; mc = f"{f}ْ{a}َ{l}ّ"; mfull = f"{f}ْ{a}َ{l}ِ{l}"
    return idgham(entry("الْبَابُ التَّاسِعُ اِفْعَلَّ — مُضَاعَفٌ", "اِفْعَلَّ يَفْعَلُّ", f"اِ{f}ْ{a}ِ{l}َا{l}", f"مُ{f}ْ{a}َ{l}ّ", mazi14(c, full), mudari14("َ", mc, mfull),
                        [c + "َ", c + "َا", c + "ُوا", c + "ِي", c + "َا", f"اِ{f}ْ{a}َ{l}ِ{l}ْنَ"], "يَ" + mc + "َ", "يَ" + mc + "َ", "تَ" + mc + "َ",
                        note="بَابُ الْأَلْوَانِ وَالْعُيُوبِ: تُدْغَمُ لَامُهُ مَا تَحَرَّكَتِ الثَّانِيَةُ، وَيُفَكُّ الْإِدْغَامُ إِذَا سَكَنَتْ."))
def XI(f, a, l):
    c = f"اِ{f}ْ{a}َا{l}ّ"; full = f"اِ{f}ْ{a}َا{l}َ{l}"; mc = f"{f}ْ{a}َا{l}ّ"; mfull = f"{f}ْ{a}َا{l}ِ{l}"
    return idgham(entry("بَابُ الِافْعِيلَالِ: اِفْعَالَّ يَفْعَالُّ — مُضَاعَفٌ", "اِفْعَالَّ يَفْعَالُّ", f"اِ{f}ْ{a}ِي{l}َا{l}", f"مُ{f}ْ{a}َا{l}ّ", mazi14(c, full), mudari14("َ", mc, mfull),
                        [c + "َ", c + "َا", c + "ُوا", c + "ِي", c + "َا", f"اِ{f}ْ{a}َا{l}ِ{l}ْنَ"], "يَ" + mc + "َ", "يَ" + mc + "َ", "تَ" + mc + "َ",
                        note="مَا كَانَ مَاضِيهِ عَلَى سِتَّةِ أَحْرُفٍ مِنْ بَابِ الْأَلْوَانِ: تُدْغَمُ لَامُهُ مَا تَحَرَّكَتِ الثَّانِيَةُ، وَيُفَكُّ الْإِدْغَامُ إِذَا سَكَنَتْ."))
V["ihmarra"]    = IX("ح", "م", "ر")
V["ibyadda"]    = IX("ب", "ي", "ض")
V["ihmarra-xi"] = XI("ح", "م", "ر")
V["iswadda-xi"] = XI("س", "و", "د")
V["ibyadda-xi"] = XI("ب", "ي", "ض")
IFAWALA = "بَابُ الِافْعِيعَالِ: اِفْعَوْعَلَ يَفْعَوْعِلُ"
V["ishawshaba"] = derived(IFAWALA, "اِفْعَوْعَلَ يَفْعَوْعِلُ", "َ", "اِعْشَوْشَب", "عْشَوْشِب", "اِعْشَوْشِب", "اِعْشِيشَاب", "مُعْشَوْشِب")
V["irawra"]     = derived_naqis(IFAWALA + " — نَاقِصٌ", "اِفْعَوْعَلَ يَفْعَوْعِلُ", "َ", "اِعْرَوْرَ", "عْرَوْر", "i", "اِعْرَوْر", "اِعْرِيرَاء", "مُعْرَوْرٍ (الْمُعْرَوْرِي)", "مُعْرَوْرًى", "اُعْرُورِيَ", "يُعْرَوْرَى")
V["islanqa"]    = derived_naqis("بَابُ الِافْعِنْلَاءِ: اِفْعَنْلَى يَفْعَنْلِي — نَاقِصٌ", "اِفْعَنْلَى يَفْعَنْلِي", "َ", "اِسْلَنْقَ", "سْلَنْق", "i", "اِسْلَنْق", "اِسْلِنْقَاء", "مُسْلَنْقٍ (الْمُسْلَنْقِي)")
V["ijlawwadha"] = derived("بَابُ الِافْعِوَّالِ: اِفْعَوَّلَ يَفْعَوِّلُ", "اِفْعَوَّلَ يَفْعَوِّلُ", "َ", "اِجْلَوَّذ", "جْلَوِّذ", "اِجْلَوِّذ", "اِجْلِوَّاذ", "مُجْلَوِّذ")

V["abqa-v"]   = derived_naqis(B4 + " — نَاقِصٌ", W4, "ُ", "أَبْقَ", "بْق", "i", "أَبْق", "إِبْقَاء", "مُبْقٍ (الْمُبْقِي)", "مُبْقًى", "أُبْقِيَ", "يُبْقَى")
V["naja-iii"] = derived_naqis(B3 + " — نَاقِصٌ", W3, "ُ", "نَاجَ", "نَاج", "i", "نَاج", "مُنَاجَاة", "مُنَاجٍ (الْمُنَاجِي)", "مُنَاجًى", "نُوجِيَ", "يُنَاجَى")
V["itada-transgress"] = derived_naqis(B8 + " — نَاقِصٌ", W8, "َ", "اِعْتَدَ", "عْتَد", "i", "اِعْتَد", "اِعْتِدَاء", "مُعْتَدٍ (الْمُعْتَدِي)", "مُعْتَدًى (عَلَيْهِ)", "اُعْتُدِيَ", "يُعْتَدَى")
